# The band: every instrument into one mixer.
mixer band {
  gains 0 0 0 0 0
  from pad.audio -> audio1
  from arp.audio -> audio2
  from bass.audio -> audio3
  from bell.audio -> audio4
  from lead.audio -> audio5
}

# master "out": The master: what reaches it is what you hear. Every song has exactly one.
master out {
  from band.audio -> audio
}

# The composition line: the name of the song, the AMPLE version it is written for (ample 1), the tempo in beats per minute and the master seed.
# tip: change the tempo (100) to hear it faster or slower; the notes keep their place in the bars.
composition "Music Welcome (100 bpm)" { ample 1  tempo 100  master-seed 20261017 }

# Welcome: intro 4, verse1 8, chorus1 8, verse2 8, bridge 4, chorus2 8, outro 4 (bars), 44 bars at 100 bpm
